/** infra/preview/preview-php.ini */
export const previewPhpIni: string =
  "; Settings of a preview's PHP on every stack (docs/plan/62, Т21): what the WordPress image gave\n; (error-logging.ini, opcache-recommended.ini; preview-apache.conf overrides revalidate_freq),\n; and mail that leaves nothing. A stack adds its own through PHP_INI_SCAN_DIR.\nerror_reporting = E_ERROR | E_WARNING | E_PARSE | E_CORE_ERROR | E_CORE_WARNING | E_COMPILE_ERROR | E_COMPILE_WARNING | E_RECOVERABLE_ERROR\ndisplay_errors = Off\ndisplay_startup_errors = Off\nlog_errors = On\nerror_log = /dev/stderr\nlog_errors_max_len = 1024\nignore_repeated_errors = On\nignore_repeated_source = Off\nhtml_errors = Off\nopcache.memory_consumption=128\nopcache.interned_strings_buffer=8\nopcache.max_accelerated_files=4000\nopcache.revalidate_freq=2\nsendmail_path = /usr/local/lib/raditi/no-sendmail\n"

/** infra/preview/prologue.php */
export const prologuePhp: string =
  "<?php\n/**\n * The first thing the generated configuration of a stack does: `require` of this file, which the\n * platform writes next to the settings file on every ensure, outside the tree. No secret here.\n * It answers 503 until the settings are there, marks the page (`ready.header`) and makes the\n * request look like one to the preview's own address. $raditi_preview stays for the configuration,\n * which unsets it.\n */\n$raditi_preview = (static function () {\n    $raw = @file_get_contents('/run/raditi/preview/settings.json');\n    $settings = is_string($raw) ? json_decode($raw, true, 32) : null;\n    if (!is_array($settings) || ($settings['v'] ?? null) !== 2\n        || !is_string($settings['origin'] ?? null) || !is_string($settings['productionOrigin'] ?? null)) {\n        if (PHP_SAPI !== 'cli' && !headers_sent()) {\n            http_response_code(503);\n            header('Content-Type: text/plain; charset=utf-8');\n            header('Retry-After: 5');\n        }\n        echo \"Предпросмотр ещё не готов. Обновите страницу через несколько секунд.\\n\";\n        exit(1);\n    }\n    return $settings;\n})();\nif (PHP_SAPI !== 'cli' && !headers_sent()) {\n    header('X-Raditi-Preview: 1');\n}\n$raditi_origin = parse_url($raditi_preview['origin']);\nif (is_array($raditi_origin) && isset($raditi_origin['host'])) {\n    $_SERVER['HTTP_HOST'] = $raditi_origin['host'] . (isset($raditi_origin['port']) ? ':' . $raditi_origin['port'] : '');\n    $_SERVER['SERVER_NAME'] = $raditi_origin['host'];\n    // The gateway ends TLS: an https preview is https to the site too, or it redirects in a loop.\n    if (($raditi_origin['scheme'] ?? '') === 'https') {\n        $_SERVER['HTTPS'] = 'on';\n        $_SERVER['SERVER_PORT'] = (string) ($raditi_origin['port'] ?? 443);\n    } else {\n        unset($_SERVER['HTTPS']);\n    }\n}\nunset($raditi_origin);\n"

/** infra/preview/site-apache.conf */
export const siteApacheConf: string =
  '# Apache of a preview of any stack (docs/plan/62, Т21): the whole server configuration, in place\n# of the image\'s apache2.conf. The server runs as the unprivileged user it is started as, on\n# 127.0.0.1:8081 behind the gateway of the preview\'s own container, with a read-only root file\n# system: its run and lock folders are on the tmpfs /tmp. No .htaccess is read: the import leaves\n# them out and a site\'s PHP could write one, so the recipe of a stack puts its rewrite rules at the\n# mark below.\n\nServerRoot "/etc/apache2"\nDefaultRuntimeDir /tmp/apache2/run\nPidFile /tmp/apache2/run/apache2.pid\nMutex file:/tmp/apache2/lock default\nTimeout 60\nKeepAlive On\nMaxKeepAliveRequests 100\nKeepAliveTimeout 5\nHostnameLookups Off\nServerName localhost\nServerTokens Prod\nServerSignature Off\nTraceEnable Off\nLimitRequestBody 33554432\n\nErrorLog /proc/self/fd/2\nLogLevel warn\nLogFormat "%h %l %u %t \\"%r\\" %>s %O \\"%{Referer}i\\" \\"%{User-Agent}i\\"" combined\nCustomLog /proc/self/fd/1 combined\n\n# The modules the image enabled, PHP and mod_rewrite among them.\nIncludeOptional mods-enabled/*.load\nIncludeOptional mods-enabled/*.conf\n<IfModule !rewrite_module>\n    LoadModule rewrite_module /usr/lib/apache2/modules/mod_rewrite.so\n</IfModule>\n\n# The code a sync, a reset or a rebuild writes is what the next request runs: the image\'s\n# opcache-recommended.ini looks at a file\'s time only every 2 s, and a check of the agent\'s\n# browser right after a sync would see the code it had before (stand R12). Speed does not\n# matter in a preview.\n<IfModule php_module>\n    php_admin_flag opcache.validate_timestamps on\n    php_admin_value opcache.revalidate_freq 0\n</IfModule>\n<IfModule php7_module>\n    php_admin_flag opcache.validate_timestamps on\n    php_admin_value opcache.revalidate_freq 0\n</IfModule>\n\n# A few workers: a preview has one visitor and a memory limit.\n<IfModule mpm_prefork_module>\n    StartServers 2\n    MinSpareServers 1\n    MaxSpareServers 4\n    MaxRequestWorkers 16\n    MaxConnectionsPerChild 500\n</IfModule>\n\nListen 127.0.0.1:8081\n\n<Directory />\n    Options None\n    AllowOverride None\n    Require all denied\n</Directory>\n\nDocumentRoot /var/www/html\n<Directory /var/www/html>\n    Options SymLinksIfOwnerMatch\n    AllowOverride None\n    Require all granted\n    DirectoryIndex index.php index.html\n    # RADITI_SITE_RULES\n</Directory>\n\n<FilesMatch "\\.php$">\n    SetHandler application/x-httpd-php\n</FilesMatch>\n\n# Hidden files and folders are never served, .well-known aside.\n<FilesMatch "^\\.">\n    Require all denied\n</FilesMatch>\n<DirectoryMatch "/\\.(?!well-known(?:/|$))">\n    Require all denied\n</DirectoryMatch>\n'
